import { expect, test } from '@playwright/test';
import { mkdirSync, writeFileSync } from 'node:fs';
import { gotoScenario } from '../e2e/helpers';

/**
 * Measures time-to-ready, search latency and JS heap for the large fixtures
 * (generated by `pnpm fixtures`). Results are written to
 * tests/performance/results.json and summarised in docs/PERFORMANCE.md.
 */
const CASES = [
  { file: 'large.pdf', query: 'invoice', budgetMs: 4000 },
  { file: 'large.csv', query: 'needle', budgetMs: 4000 },
  { file: 'large.xlsx', query: 'needle', budgetMs: 6000 },
  { file: 'large.txt', query: 'needle', budgetMs: 3000 },
  { file: 'large.json', query: 'needle', budgetMs: 3000 },
  { file: 'large.xml', query: 'needle', budgetMs: 4000 },
];

const results: Array<Record<string, unknown>> = [];

test.describe.configure({ mode: 'serial' });

for (const c of CASES) {
  test(`${c.file} stays within budget`, async ({ page }) => {
    await gotoScenario(page, 'large');
    const t0 = Date.now();
    await page.getByRole('button', { name: `Preview ${c.file}`, exact: true }).click();
    const dialog = page.getByRole('dialog');
    await expect(dialog.locator('.dsc-renderer[data-ready="true"]')).toBeVisible({ timeout: 60_000 });
    const readyMs = Date.now() - t0;
    await page.keyboard.press('Control+f');
    const t1 = Date.now();
    await page.keyboard.type(c.query);
    await expect(dialog.getByRole('status').filter({ hasText: /^\d+ of / })).toBeVisible({ timeout: 60_000 });
    const searchMs = Date.now() - t1;
    const domNodes = await page.evaluate(() => document.querySelectorAll('*').length);
    const heapMb = await page.evaluate(() => {
      const m = (performance as unknown as { memory?: { usedJSHeapSize: number } }).memory;
      return m ? Math.round(m.usedJSHeapSize / 1048576) : null;
    });
    results.push({ file: c.file, readyMs, searchMs, domNodes, heapMb });
    expect(readyMs).toBeLessThan(c.budgetMs);
    expect(domNodes).toBeLessThan(15_000); // virtualisation keeps the DOM small
  });
}

test.afterAll(() => {
  mkdirSync('tests/performance', { recursive: true });
  writeFileSync('tests/performance/results.json', `${JSON.stringify({ date: new Date().toISOString(), results }, null, 2)}\n`);
});
